list_transactions.code:
final response = await client.transactions
    .listTransactions(queryParams: {'limit': 50, 'offset': 0});
final transactions = (response.map as Map)['transactions'] as List;
for (final transaction in transactions) {
  final row = transaction as Map;
  print('${row['transaction_no']} ${row['total_records']}');
}

get_transaction.code:
final response =
    await client.transactions.getTransaction('IMPORT-2026-0001');
final transaction = response.map as Map;
print(transaction['total_records']);
for (final row in transaction['by_type'] as List) {
  print('${(row as Map)['type']} ${row['count']}');
}

list_transaction_items.code:
final response = await client.transactions.listTransactionItems(
  'IMPORT-2026-0001',
  queryParams: {'type': 'product', 'limit': 20, 'offset': 0, 'detail': 'slim'},
);
for (final item in (response.map as Map)['items'] as List) {
  print('${(item as Map)['id']} ${item['sku']} ${item['name']}');
}

